@abeldekat  Another possible solution I could manage

https://github.com/user-attachments/assets/cdf525a5-059c-4ddb-a7ab-d3546f25f227

```lua

local win_config = function()
    local has_statusline = vim.o.laststatus > 0
    local pad = vim.o.cmdheight + (has_statusline and 1 or 0)
    local notify_lps = {
        anchor = "SE",
        title = "",
        footer = {
            {
                (vim.b.icon or "") .. (" %s"):format((vim.b.tool or "")),
                "WarningMsg",
            },
        },
        footer_pos = "right",
        border = "solid",
        col = vim.o.columns,
        row = vim.o.lines - pad,
    }
    --stylua: ignore
    return notify_lps
end

local content = {
    format = function(str)
        if vim.b.not_lsp_progress then
            return str.msg
        end
        local parts = vim.split(str.msg, ": ")
        local action = parts[2] and parts[2] or ""
        local tool = parts[1] or ""
        -- stylua: ignore
        local progress_match = action:match("(%d+/[%d]+)") or ""
        local percent_match = action:match("(%d+%%)") or ""
        -- stylua: ignore
        action = action:gsub("%s*%d+/%d+", ""):gsub("%s*%(%d+%%%)", ""):gsub("%s*%([^)]+%)", ""):gsub("%s+$", "")
        action = table.concat(vim.list_slice(vim.split(action, " "), 1, 2), " ")

        vim.b.tool = tool

        str.hl_group = "Comment"

        -- stylua: ignore
        return string.format(
            "%-5s %-4s %s",
            progress_match, percent_match, action
        )
    end,
}

MiniNotify.setup({
    winblend = 0,
    window = { config = win_config },
    content = content,
    lsp_progress = {
        enable = true,
        duration_last = 1000,
    },
})

vim.notify = MiniNotify.make_notify()
local notify = vim.notify
vim.notify = function(msg, level, opts)
    opts = opts or {}
    vim.b.tool = opts.title
    vim.b.not_lsp_progress = true
    vim.b.icon = opts.icon or ""
    vim.b.mininotify_config = {
        window = {
            config = function()
                local notify_lsp = {
                    anchor = "NE",
                    title = {
                        {
                            ((vim.b.tool or "") or ""),
                            "WarningMsg",
                        },
                    },
                    title_pos = "center",
                }
                return notify_lsp
            end,
        },
    }
    notify(msg, level, opts)
    vim.defer_fn(function()
        vim.b.mininotify_config = {
            window = {
                config = win_config,
            },
        }
        vim.b.not_lsp_progress = false
    end, 500)
end
```
